pub(super) fn build_separating(
    face: &Facet,
    finite: &Bounds,
    certificates: Option<&InteriorCertificates<'_>>,
    b: &mut Budget,
) -> Result<Self, Failure> {
    let entry = b.retained_memberships();
    let result = b.with_retained(32, |b| {
        Self::build_separating_admitted(face, finite, certificates, b)
    });
    if result.is_err() {
        b.release(b.retained_memberships() - entry);
    }
    result
}
