        for (owner, row) in self.owners.values().enumerate() {
            b.state([
                self.members,
                self.owners.len(),
                row.equations.len(),
                owner,
                0,
                32,
                0,
                0,
            ]);
            b.step(1)?;
            if row.outside || row.separated {
                continue;
            }
            let mut boundary = false;
            let mut outside = false;
            for (ordinal, equation) in row.equations.iter().enumerate() {
                b.state([
                    self.members,
                    self.owners.len(),
                    row.equations.len(),
                    owner,
                    ordinal,
                    32,
                    0,
                    0,
                ]);
