pub(super) fn separated(&self, owner: u32, b: &mut Budget) -> Result<bool, Failure> {
    if self.owners.is_empty() {
        return Ok(false);
    }
    log_cost(self.owners.len(), b)?;
    Ok(self.owners.get(&owner).is_some_and(|row| row.separated))
}
